  drawText(ctx,'HIGH SCORE',(W-textWidth('HIGH '+S.hiScore))/2,4,PAL.red); drawText(ctx,'HIGH '+S.hiScore,(W-textWidth('HIGH '+S.hiScore))/2,4,PAL.red); // label+value together
  drawText(ctx,String(S.hiScore),6,12,PAL.white,'left');

  // tractor beam (drawn under enemies so it looks projected from the boss)
  if(S.beam) drawBeam();

