  // shots
  ctx.fillStyle='#cfe4ff'; for(const s of S.shots)ctx.fillRect(Math.round(s.x)-1,Math.round(s.y)-3,2,6);
  ctx.fillStyle='#ffd0d0'; for(const s of S.eShots)ctx.fillRect(Math.round(s.x)-1,Math.round(s.y)-2,2,5);

