  if(S.player&&S.player.alive&&!S.player.captured){ const p=S.player;
    if(p.dual){ ctx.drawImage(playerSprite,Math.round(p.x-13),Math.round(p.y-7)); ctx.drawImage(playerSprite,Math.round(p.x+1),Math.round(p.y-7)); }
    else { ctx.drawImage(playerSprite,Math.round(p.x-6),Math.round(p.y-7)); } }

  // particles
  for(const pt of S.parts){ if(pt.type==='exp')drawExplosion(ctx,pt.x,pt.y,pt.frame,pt.size); else {ctx.globalAlpha=clamp(pt.life/20,0,1);ctx.fillStyle=pt.color;ctx.fillRect(Math.round(pt.x),Math.round(pt.y),2,2);ctx.globalAlpha=1;} }

  // HUD bottom
  for(let i=0;i<S.lives;i++){ ctx.drawImage(playerSprite,4+i*13,H-16); }
  drawText(ctx,'CREDIT',W-40,H-16,PAL.white,'left'); drawText(ctx,String(S.stageFlags),W-8,H-16,PAL.white,'right');
  for(let i=0;i<S.flags.length;i++){ drawFlag(ctx,W-9-i*12,H-13,(i%2)?PAL.red:PAL.cyan); }

  // overlays
  if(S.mode==='gameover'){ S.goTimer++; ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H); drawText(ctx,'GAME OVER',W/2,120,PAL.red,'center'); if(S.goTimer>60){drawText(ctx,'PRESS ENTER',W/2,140,PAL.white,'center');} }
  else {
    if(S.respawnDelay>0||S.readyTimer>0) drawText(ctx,'READY',W/2,150,(Math.floor(S.frame/16)%2)?PAL.red:PAL.yellow,'center');
    if(S.msgTimer>0 && S.mode==='playing' && !S.challenge) drawText(ctx,S.msg,W/2,132,PAL.cyan,'center');
  }
  if(S.paused){ ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H); drawText(ctx,'PAUSED',W/2,140,PAL.yellow,'center'); }
  if(S.muted){ drawText(ctx,'MUTE',6,H-16,PAL.red,'left'); }

  // challenge stage header
  if(S.challenge && S.mode==='playing'){ drawText(ctx,'CHALLENGING STAGE',W/2,150,(Math.floor(S.frame/14)%2)?PAL.yellow:PAL.white,'center'); }
}

function drawEnemy(e){
  let spr;
  if(e.type==='zako')spr=(e.flap?ENEMY.zako.b:ENEMY.zako.a);
  else if(e.type==='goei')spr=(e.flap?ENEMY.goei.b:ENEMY.goei.a);
  else { const g=e.hit?['a_b','b_b']:['a_g','b_g']; spr=ENEMY.boss[e.flap?g[1]:g[0]]; }
  // rotate divers toward their travel direction (approximate)
  if(e.state==='dive'||e.state==='escort'||e.state==='entry'){ const ang=(e.angle||Math.PI/2)-Math.PI/2; ctx.save();ctx.translate(Math.round(e.x),Math.round(e.y));ctx.rotate(clamp(ang,-0.5,0.5));ctx.drawImage(spr,-spr.width/2,-spr.height/2);ctx.restore(); }
  else ctx.drawImage(spr,Math.round(e.x-spr.width/2),Math.round(e.y-spr.height/2));
}

function drawBeam(){
  const b=S.beam,e=b.enemy; if(!e)return; const prog=clamp(b.progress,0,1); const topY=e.y+6, botY=PLAYER_Y+8;
  const topW=4, botW=54*prog; const h=botY-topY;
  for(let i=0;i<Math.floor(h);i++){ const t=i/h; const ww=topW+(botW-topW)*t; const y=Math.round(topY+i); const a=(0.12+0.16*Math.abs(Math.sin(S.frame*0.25-t*6)))*(1-t*0.35);
    ctx.fillStyle='rgba(70,140,255,'+a.toFixed(3)+')'; ctx.fillRect(Math.round(e.x-ww/2),y,Math.max(1,Math.round(ww)),1); }
  // bright core
  ctx.fillStyle='rgba(200,230,255,0.5)'; ctx.fillRect(Math.round(e.x-1),topY,2,h*prog);
}

